import{_ as o,a0 as s,w as l,s as d,ao as x,I as i,x as e,a1 as t,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"2013：Linux的黄金之年-十大杰出成就 | LCTT x X-CMD","titleTemplate":false,"description":"2013：Linux的黄金之年-十大杰出成就 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"2013：Linux的黄金之年-十大杰出成就 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2013：Linux的黄金之年-十大杰出成就 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/2013：The Golden Year for Linux – 10 Biggest Linux Achievements","title":"2013：Linux的黄金之年-十大杰出成就","tag":"201401","desc":""},"relativePath":"201401/2013：The Golden Year for Linux – 10 Biggest Linux Achievements.md","filePath":"[post].md"}'),h={name:"201401/2013：The Golden Year for Linux – 10 Biggest Linux Achievements.md"};function p(u,n,g,m,L,f){const a=s("Link");return l(),d("div",null,[n[11]||(n[11]=x('<h1 id="_2013-linux的黄金之年-十大杰出成就" tabindex="-1">2013：Linux的黄金之年-十大杰出成就 <a class="header-anchor" href="#_2013-linux的黄金之年-十大杰出成就" aria-label="Permalink to “2013：Linux的黄金之年-十大杰出成就”">​</a></h1><p><strong>2013年</strong>已经过去。这一年见证了许多里程碑事件，使得2013年可以称得上是一个<strong>Linux的黄金之年</strong>。其中一些成果在<strong>FOSS</strong>和<strong>Linux</strong>世界更可以称得上是举世瞩目的成就。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2013/12/Year-2013-Linux.jpg" alt="2013 Year of Linux"></p><h3 id="_1-android的上升趋势" tabindex="-1">1.Android的上升趋势 <a class="header-anchor" href="#_1-android的上升趋势" aria-label="Permalink to “1.Android的上升趋势”">​</a></h3><p>2013年，Android手机达到了每日<strong>150万</strong>的激活量记录。不用说，正是Android的<strong>Linux内核</strong>以及它在该方面的狂热贡献使其达到了今天的标杆地位，这一趋势还将在未来的日子里一直持续下去。</p><h3 id="_2-raspberry-pi-树莓派" tabindex="-1">2. Raspberry pi 树莓派 <a class="header-anchor" href="#_2-raspberry-pi-树莓派" aria-label="Permalink to “2. Raspberry pi 树莓派”">​</a></h3><p><strong>Raspberry pi</strong>，低成本单片计算机历史上的最伟大发明之一。它在学校和其他很多地方极大地推广了Linux，同时在FOSS社区中也有很高的欢迎程度，这一状况也仍将继续。</p><h3 id="_3-debian上太空" tabindex="-1">3. Debian上太空 <a class="header-anchor" href="#_3-debian上太空" aria-label="Permalink to “3. Debian上太空”">​</a></h3><p>Debian，众多优秀Linux发行版中的其中一款高端发行版。2013年三月下旬的一次<strong>航天飞机</strong>任务中就使用了Debian负责实验的控制。实验的主要内容是尝试无土植物栽培的新方法，从而为宇航员提供空气和食物。</p><h3 id="_4-steamos的崛起" tabindex="-1">4. SteamOS的崛起 <a class="header-anchor" href="#_4-steamos的崛起" aria-label="Permalink to “4. SteamOS的崛起”">​</a></h3><p>SteamOS，基于Debian发行版，用于<strong>Stream Machine Game Console游戏终端</strong>，已经于<strong>2013年12月</strong>中旬发布。GNU/Linux开始涉足于游戏环境，这对广大宅男极客来说当然是喜闻乐见喜大普奔。</p><h3 id="_5-linux的平板应用" tabindex="-1">5. Linux的平板应用 <a class="header-anchor" href="#_5-linux的平板应用" aria-label="Permalink to “5. Linux的平板应用”">​</a></h3><p>查看<strong>亚马逊</strong>的平板销量，排名前十的平板都是Android操作系统。苹果和微软的平板则排在第11和12位，远远地被抛在后面，这对于FOSS社区来说确实是一个振奋人心的消息。</p><h3 id="_6-chromebooks" tabindex="-1">6. Chromebooks <a class="header-anchor" href="#_6-chromebooks" aria-label="Permalink to “6. Chromebooks”">​</a></h3><p>Chromebooks之所以能在笔记本电脑市场赢得一席之地，是由于比起微软等专属平台，诸如三星，华硕等许多高端制造商给了GNU/Linux类操作系统更多的空间。</p><h3 id="_7-the-firefox-os-火狐操作系统" tabindex="-1">7. The Firefox OS 火狐操作系统 <a class="header-anchor" href="#_7-the-firefox-os-火狐操作系统" aria-label="Permalink to “7. The Firefox OS 火狐操作系统”">​</a></h3><p>Firefox OS是基于Linux和FOSS的开源操作系统，主要用于智能手机和平板，发布于<strong>2013年4月</strong>下旬。基于<strong>ARM</strong>构架的移动设备Linux发行版显示出了广阔的前景。</p><h3 id="_8-kali发布" tabindex="-1">8. Kali发布 <a class="header-anchor" href="#_8-kali发布" aria-label="Permalink to “8. Kali发布”">​</a></h3><p>来自BackTrack Linux的开发者发布了<strong>Kali Linux</strong>。Kali是是基于Debian的Linux发行版，其母系统或者说其前身(BT Linux)，主要用于渗透测试，并分享了大量的Debian版本库，成为了最为丰富的一个发行版。Kail仍保持着在刚发布后的很短时间内超高下载量的记录。</p><h3 id="_9-android-kitkat" tabindex="-1">9. Android Kitkat <a class="header-anchor" href="#_9-android-kitkat" aria-label="Permalink to “9. Android Kitkat”">​</a></h3><p>尽管之前预测的发布版本是<strong>5.0 Key Lime Pie</strong>，经过万众期待后，最新发布的android版本被命名为<strong>Kitkat</strong>，Google宣布<strong>Android 4.4</strong>又名<strong>KitKat 4于2013年9月发布</strong>。Kitkat进行了优化更新，能在具有最小的<strong>512 MB内存</strong>的设备上运行，这样就能够支持众多各种各样的设备。</p><h3 id="_10-linux-在汽车上的应用" tabindex="-1">10. Linux 在汽车上的应用 <a class="header-anchor" href="#_10-linux-在汽车上的应用" aria-label="Permalink to “10. Linux 在汽车上的应用”">​</a></h3><p>截至目前，Linux被应用于各种设备，从腕表到遥控器，再到太空飞船，所以<strong>Linux在汽车上的应用</strong>并不让人意外。但当Linux的作用表现在<strong>汽车趋势杂志</strong>的年度车上时仍然令人惊讶。2013年被选为优胜候选的两个车型，都运行Linux系统。</p><p>2013年已经过去，但故事远没有结束，我们可能错过了一些重要的里程碑，你可以在评论部分告诉我们。2014年，未来，还在继续……</p><hr>',25)),i("p",null,[n[1]||(n[1]=e("via: ",-1)),t(a,{href:"http://www.tecmint.com/2013-the-golden-year-for-linux-and-foss/"},{default:r(()=>[...n[0]||(n[0]=[e("http://www.tecmint.com/2013-the-golden-year-for-linux-and-foss/",-1)])]),_:1})]),i("p",null,[n[4]||(n[4]=e("译者：",-1)),t(a,{href:"https://github.com/yechunxiao19"},{default:r(()=>[...n[2]||(n[2]=[e("乌龙茶",-1)])]),_:1}),n[5]||(n[5]=e(" 校对：",-1)),t(a,{href:"http://blog.csdn.net/tinyeyeser"},{default:r(()=>[...n[3]||(n[3]=[e("Mr小眼儿",-1)])]),_:1})]),i("p",null,[n[8]||(n[8]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...n[6]||(n[6]=[e("LCTT",-1)])]),_:1}),n[9]||(n[9]=e(" 原创翻译，",-1)),t(a,{href:"http://linux.cn/"},{default:r(()=>[...n[7]||(n[7]=[e("Linux中国",-1)])]),_:1}),n[10]||(n[10]=e(" 荣誉推出",-1))])])}const T=o(h,[["render",p]]);export{k as __pageData,T as default};
